// One output item per user -> n8n sends one email each.
// No rows in means no items out, so nobody receives an empty nudge.
const byUser = new Map();
for (const { json: r } of $input.all()) {
  if (!byUser.has(r.email)) byUser.set(r.email, []);
  byUser.get(r.email).push(r);
}

// Titles and platforms are free text typed by users, so they are escaped
// before going anywhere near an HTML email body.
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

return [...byUser].map(([email, items]) => {
  const rows = items.map((i) => `
    <tr>
      <td style="padding:8px 12px 8px 0;vertical-align:top">${
        i.poster ? `<img src="${esc(i.poster)}" alt="" width="46" style="border-radius:6px;display:block">` : ''
      }</td>
      <td style="padding:8px 0;vertical-align:top">
        <div style="font-weight:600;color:#0f172a">${esc(i.title)}</div>
        <div style="font-size:13px;color:#64748b">${esc(i.platform)} &middot; idle ${i.days_idle} days</div>
      </td>
    </tr>`).join('');

  const html = `<div style="font-family:system-ui,-apple-system,sans-serif;max-width:520px">
  <p style="color:#0f172a">You have <strong>${items.length}</strong> title${items.length === 1 ? '' : 's'} still marked <em>watching</em>:</p>
  <table cellpadding="0" cellspacing="0">${rows}</table>
  <p style="font-size:12px;color:#94a3b8">Finish them or drop them &mdash; either way the list gets honest again.</p>
</div>`;

  return { json: { email, count: items.length, html } };
});
